import argparse, base64, datetime, hashlib, json, os, re, subprocess, sys, urllib.error, urllib.request

MAX_INT = 2**53 - 1
KINDS = ("plan", "verdict", "orphan")
OUTCOMES = ("pass", "fail", "inconclusive")
